  "id": "Gdal_Translate",
  "title": "Convert raster data from one format to another. ",
  "description": "http://www.gdal.org/gdal_translate.html",
  "version": "1.0.0",
  "jobControlOptions": [
    "sync-execute",
    "async-execute",
    "dismiss"
  ],
